   156→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   157→        const ctx = await initContext(projectContext.path);
   158→        const meta = await loadMetaContext(ctx);
   159→
   160→        // Start with all observations
   161→        let filtered = meta.observations || [];
   162→
   163→        // AC: @api-contract ac-18 - Filter by resolved status
   164→        if (query.resolved !== undefined) {
   165→          const resolvedFilter = query.resolved === 'true';
   166→          filtered = filtered.filter((obs) => {
   167→            const isResolved = !!obs.resolved_at;
   168→            return isResolved === resolvedFilter;
   169→          });
   170→        }
   171→
   172→        // Optional type filter (not in ACs but useful)
   173→        if (query.type) {
   174→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
   175→          filtered = filtered.filter((obs) => typeFilters.includes(obs.type));
   176→        }
   177→
   178→        // Sort by created_at descending (newest first)
   179→        const sorted = [...filtered].sort(
   180→          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
   181→        );
   182→
   183→        return {
   184→          items: sorted,
